// Guardrail for the drafted reply: structure, length, cited knowledge-base ids
// must exist, and money amounts in the reply must appear in the snippets the
// model was given (simple hallucination check). Problems do not drop the
// ticket - they route it to "manual reply needed".
// Mode: Run once for each item.

const input = $input.item.json;
const ctx = $('Retrieve FAQ snippets').item.json;
const errors = [];
const warnings = [];
// --- included from src/code/shared/read-llm-json.js ---------------------------
// The Basic LLM Chain returns one of three shapes, depending on model setup:
//   { text: "<raw model output>" }      (string output, e.g. with a fallback model)
//   { ...parsedJsonObject }             (JSON mode: n8n already parsed it)
//   { ...inputFields, error: "..." }    (error output of the chain node - it keeps
//                                        the input item's fields and adds "error")
// Returns { data, raw, error } where data is a plain object or null.
function readLlmJson(input) {
  if (input && input.error) {
    const e = input.error;
    return { data: null, raw: '', error: 'LLM request failed: ' + String((e && e.message) || e).slice(0, 300) };
  }
  let raw;
  let data = null;
  if (input && typeof input.text === 'string' && Object.keys(input).length === 1) {
    raw = input.text;
    const cleaned = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    try { data = JSON.parse(cleaned); } catch {
      const m = cleaned.match(/\{[\s\S]*\}/);
      if (m) { try { data = JSON.parse(m[0]); } catch { /* not JSON */ } }
    }
  } else {
    data = input;
    raw = JSON.stringify(input);
  }
  if (!data || typeof data !== 'object' || Array.isArray(data)) {
    return { data: null, raw: String(raw || ''), error: 'Output is not a single JSON object' };
  }
  return { data, raw: String(raw), error: null };
}
// --- end include ----------------------------------------------------------------

const parsed = readLlmJson(input);
const data = parsed.data;
if (parsed.error) errors.push(parsed.error);

let draft = null;
if (data) {
  draft = {
    subject: typeof data.subject === 'string' && data.subject.trim() ? data.subject.trim().slice(0, 200) : '',
    body: typeof data.body === 'string' ? data.body.trim() : '',
    faq_ids_used: Array.isArray(data.faq_ids_used) ? data.faq_ids_used.map(String) : [],
    needs_human_attention: Boolean(data.needs_human_attention),
    confidence: Math.max(0, Math.min(1, Number(data.confidence) || 0)),
  };
  if (draft.body.length < 30) errors.push('body: too short');
  if (draft.body.length > 3000) errors.push('body: too long');
  const unknown = draft.faq_ids_used.filter((id) => !ctx.kb_ids.includes(id));
  if (unknown.length) errors.push('faq_ids_used contains ids that were not provided: ' + unknown.join(', '));

  // Every money amount in the reply must be present in the provided snippets.
  const amounts = draft.body.match(/[$€£]\s?\d[\d,.]*|\d[\d,.]*\s?(?:USD|EUR|GBP|%)/g) || [];
  const ungrounded = amounts.filter((a) => !ctx.kb_snippets.includes(a.replace(/\s/g, '').replace(/[.,]$/, '')));
  if (ungrounded.length) warnings.push('amounts not found in knowledge base: ' + ungrounded.join(', '));
}

const usable = errors.length === 0;
const needsAttention = !usable || warnings.length > 0 || (draft && draft.needs_human_attention);

return {
  json: {
    draft: usable ? draft : null,
    draft_usable: usable,
    draft_errors: errors,
    draft_warnings: warnings,
    needs_human_attention: Boolean(needsAttention),
  },
};

// Assemble the ticket (email + classification + draft) and the Slack approval
// message. Mode: Run once for each item.

const cfg = $('Config').first().json;
const norm = $('Normalize email').item.json;
const { classification } = $('Parse classification').item.json;
const d = $input.item.json; // from "Validate draft"
const email = norm.email;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const quote = (s, max) => {
  const t = String(s ?? '');
  return esc(t.length > max ? t.slice(0, max) + '…' : t).split('\n').map((l) => '> ' + l).join('\n');
};
const urgencyIcon = { critical: ':red_circle:', high: ':large_orange_circle:', normal: ':large_blue_circle:', low: ':white_circle:' }[classification.urgency] || '';

const approvalText = [
  `${urgencyIcon} *Support reply needs approval* - ${classification.category} · ${classification.urgency} urgency · ${classification.sentiment}`,
  `*From:* ${esc(email.from_name)} ${esc(email.from_address)}`,
  `*Subject:* ${esc(email.subject)}`,
  `*Summary:* ${esc(classification.summary)}`,
  `*Customer wrote:*`,
  quote(email.body, 700),
  `*Proposed reply:*`,
  quote(d.draft ? d.draft.body : '', 2500),
  `_Knowledge used: ${d.draft && d.draft.faq_ids_used.length ? d.draft.faq_ids_used.join(', ') : 'none'} · confidence ${d.draft ? d.draft.confidence : 0}_`,
  d.needs_human_attention ? ':warning: *Flagged for careful review:* ' + esc([...(d.draft_warnings || []), d.draft && d.draft.needs_human_attention ? 'model asked for human attention' : ''].filter(Boolean).join('; ')) : '',
  'Approve to send this reply from the support inbox. Reject to handle it manually (the email stays unread).',
].filter(Boolean).join('\n');

const manualText = [
  `:warning: *Support email needs a manual reply* (no usable AI draft) - ${classification.category} · ${classification.urgency} urgency`,
  `*From:* ${esc(email.from_name)} ${esc(email.from_address)}`,
  `*Subject:* ${esc(email.subject)}`,
  `*Summary:* ${esc(classification.summary)}`,
  `*Reason:* ${esc((d.draft_errors || []).join('; ') || 'n/a')}`,
].join('\n');

return {
  json: {
    dry_run: Boolean(cfg.dryRun) || norm.is_sample,
    email,
    classification,
    draft: d.draft,
    draft_usable: d.draft_usable,
    draft_errors: d.draft_errors,
    draft_warnings: d.draft_warnings,
    needs_human_attention: d.needs_human_attention,
    slack_approval_text: approvalText,
    slack_manual_text: manualText,
  },
};

// One flat row per processed email for the "Support log" sheet.
// Works for every path (skipped, spam, dry run, sent, rejected, ...):
// nodes that did not run for this item are simply treated as empty.
// Mode: Run once for each item.

const get = (node) => {
  try { return $(node).item.json; } catch { return null; }
};
const cfg = $('Config').first().json;
const norm = get('Normalize email') || {};
const cls = get('Parse classification');
const ticket = get('Build ticket');
const outcome = $input.item.json.outcome || 'unknown';
const email = norm.email || {};
const c = (ticket && ticket.classification) || (cls && cls.classification) || {};
const draft = ticket && ticket.draft;

return {
  json: {
    logged_at: new Date().toISOString(),
    outcome,
    message_id: email.message_id || '',
    thread_id: email.thread_id || '',
    from: email.from_address || '',
    subject: email.subject || '',
    category: c.category || '',
    sentiment: c.sentiment || '',
    urgency: c.urgency || '',
    summary: c.summary || norm.skip_reason || '',
    classification_valid: cls ? cls.classification_valid : '',
    faq_ids_used: draft ? draft.faq_ids_used.join(', ') : '',
    draft_confidence: draft ? draft.confidence : '',
    needs_human_attention: ticket ? ticket.needs_human_attention : '',
    reply_subject: draft ? draft.subject : '',
    reply_body: draft ? draft.body : '',
    dry_run: Boolean(cfg.dryRun) || Boolean(norm.is_sample),
  },
};
